/**
 * Meridian's service worker.
 *
 * Hand-written rather than generated by Workbox, because the interesting part
 * of this file is a list of things it refuses to cache, and that list is worth
 * reading. A generated worker with a config object hides exactly the decision
 * that matters here.
 *
 * ## What is cached
 *
 * Only bytes that are identical for every person and every session:
 *
 *   - `/_next/static/*` — content-hashed by the build, so a URL never changes
 *     meaning. This is most of the app's weight and the whole speed win.
 *   - the icons, `/icon.svg`, the manifest, and `/offline`.
 *
 * ## What is never cached, and why
 *
 * **HTML pages.** Tempting, and wrong here. Some routes are Server Components
 * that render a person's data into the markup — `/trips/[id]/money` reads the
 * trip server-side. A cache is per-origin, not per-account, so a cached page
 * could outlive a sign-out and be served to whoever signs in next on a shared
 * device. Navigations therefore go to the network, and fall back to `/offline`
 * rather than to a stale page.
 *
 * **Anything from Supabase.** REST, auth, realtime and storage. All of it is
 * per-user and governed by RLS on the server; a cached copy answers with no
 * policy applied at all.
 *
 * **Signed storage URLs.** They expire in 300 seconds by design (non-negotiable
 * #3). Caching one keeps a credential alive past the window it was scoped to.
 *
 * **`/api/*`.** Route Handlers, including the MCP token exchange. Nothing there
 * is safe to replay from disk.
 *
 * So the offline story is honest: the app shell loads instantly and tells you
 * it cannot reach the network, rather than pretending to show you a plan that
 * may have changed. Real offline reads would need a per-account encrypted
 * store, and that is a different feature with different risks.
 */

/* Worker globals. `/* eslint-env *\/` is deprecated under flat config and
   becomes an error in ESLint 10, so these are declared individually. */
/* global self, caches, fetch, Response, URL */

// Bumping this invalidates every cache — the activate handler deletes anything
// that is not in CURRENT. Bump it when the cached *set* changes, not on every
// deploy: static assets are content-hashed, so their URLs already change.
const VERSION = 'v1'

const STATIC_CACHE = `meridian-static-${VERSION}`
const SHELL_CACHE = `meridian-shell-${VERSION}`
const CURRENT = [STATIC_CACHE, SHELL_CACHE]

const OFFLINE_URL = '/offline'

/** Precached at install so the offline page works the first time it is needed. */
const SHELL = [OFFLINE_URL, '/icon.svg', '/icons/icon-192.png', '/manifest.webmanifest']

/**
 * Whether a request carries or returns something belonging to one person.
 *
 * Exposed on `self` so the test suite can load this exact file and exercise the
 * real predicate rather than a copy of it that could drift. Nothing in the
 * worker reads it back off `self`.
 */
function isPrivateRequest(request) {
  const url = new URL(request.url)

  // Only GET is ever cacheable, and a mutation is never idempotent to replay.
  if (request.method !== 'GET') return true

  // Supabase: PostgREST, GoTrue, Realtime and Storage all live under the
  // project host. Storage in particular hands out signed URLs that expire.
  if (/(^|\.)supabase\.(co|in)$/i.test(url.hostname)) return true

  // Our own Route Handlers.
  if (url.pathname === '/api' || url.pathname.startsWith('/api/')) return true

  // A signed URL from anywhere. Supabase uses `token`; the others are the
  // common S3-compatible spellings, since storage may not always be Supabase.
  for (const param of ['token', 'X-Amz-Signature', 'signature', 'sig']) {
    if (url.searchParams.has(param)) return true
  }

  // Anything carrying credentials is by definition not shared bytes.
  if (request.headers.has('authorization')) return true

  return false
}

/**
 * Whether a response may be written to the cache.
 *
 * `basic` means same-origin; `cors` is allowed only for the static host cases
 * the caller has already vetted. An `opaque` response has status 0 and
 * unreadable headers, so caching one stores something we cannot inspect and
 * cannot invalidate.
 */
function isCacheableResponse(response) {
  if (!response || !response.ok) return false
  if (response.type === 'opaque' || response.type === 'opaqueredirect') return false
  const control = response.headers.get('cache-control') || ''
  if (/no-store|private/i.test(control)) return false
  return true
}

/** Immutable, content-hashed build output. Safe to serve from disk forever. */
function isImmutableAsset(url) {
  return url.pathname.startsWith('/_next/static/')
}

/** Small, shared, and changes rarely. */
function isShellAsset(url) {
  return (
    url.pathname === '/icon.svg' ||
    url.pathname === '/manifest.webmanifest' ||
    url.pathname.startsWith('/icons/')
  )
}

self.__meridian = { isPrivateRequest, isCacheableResponse, isImmutableAsset, isShellAsset }

// ---------------------------------------------------------------------------
// Lifecycle
// ---------------------------------------------------------------------------

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(SHELL_CACHE)
      // Individually rather than `addAll`, which rejects the whole install if
      // any single URL 404s. A missing icon should not leave the app with no
      // worker at all.
      await Promise.all(
        SHELL.map(async (url) => {
          try {
            const response = await fetch(url, { cache: 'reload' })
            if (isCacheableResponse(response)) await cache.put(url, response)
          } catch {
            // Offline at install time. The runtime handler will fill it later.
          }
        }),
      )
      // Take over as soon as the new worker is ready rather than waiting for
      // every tab to close. Paired with `clients.claim()` below, and safe here
      // because nothing cached is version-coupled to the page that requested it.
      await self.skipWaiting()
    })(),
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys()
      await Promise.all(
        names
          .filter((name) => name.startsWith('meridian-') && !CURRENT.includes(name))
          .map((name) => caches.delete(name)),
      )
      await self.clients.claim()
    })(),
  )
})

/**
 * The app asks for this on sign-out.
 *
 * Nothing user-specific is cached, so this is belt-and-braces rather than the
 * mechanism the privacy argument rests on — but a device changing hands should
 * not keep even a shell that hints at what was installed.
 */
self.addEventListener('message', (event) => {
  if (event.data?.type === 'CLEAR_CACHES') {
    event.waitUntil(
      (async () => {
        const names = await caches.keys()
        await Promise.all(
          names.filter((n) => n.startsWith('meridian-')).map((n) => caches.delete(n)),
        )
      })(),
    )
  }
})

// ---------------------------------------------------------------------------
// Fetch
// ---------------------------------------------------------------------------

self.addEventListener('fetch', (event) => {
  const { request } = event

  if (isPrivateRequest(request)) return // Straight to the network, untouched.

  const url = new URL(request.url)

  // Navigations: network, with the offline page as the only fallback. See the
  // note at the top for why a cached page is not on the menu.
  if (request.mode === 'navigate') {
    event.respondWith(
      (async () => {
        try {
          return await fetch(request)
        } catch {
          const cached = await caches.match(OFFLINE_URL)
          return (
            cached ??
            new Response('You are offline.', {
              status: 503,
              headers: { 'content-type': 'text/plain; charset=utf-8' },
            })
          )
        }
      })(),
    )
    return
  }

  if (url.origin !== self.location.origin) return

  if (isImmutableAsset(url)) {
    event.respondWith(cacheFirst(request, STATIC_CACHE))
    return
  }

  if (isShellAsset(url)) {
    event.respondWith(staleWhileRevalidate(request, SHELL_CACHE))
  }
})

/** For URLs whose contents cannot change. A hit never revalidates. */
async function cacheFirst(request, cacheName) {
  const cached = await caches.match(request)
  if (cached) return cached

  const response = await fetch(request)
  if (isCacheableResponse(response)) {
    const cache = await caches.open(cacheName)
    // Clone before returning: a Response body can only be read once.
    void cache.put(request, response.clone())
  }
  return response
}

/** Instant from disk, refreshed in the background for next time. */
async function staleWhileRevalidate(request, cacheName) {
  const cached = await caches.match(request)

  const network = fetch(request)
    .then(async (response) => {
      if (isCacheableResponse(response)) {
        const cache = await caches.open(cacheName)
        await cache.put(request, response.clone())
      }
      return response
    })
    .catch(() => null)

  if (cached) {
    void network // Refresh happens regardless; the cached copy answers now.
    return cached
  }
  const response = await network
  return response ?? Response.error()
}

// ---------------------------------------------------------------------------
// Push
// ---------------------------------------------------------------------------

/**
 * A pushed notification.
 *
 * The payload is deliberately thin — a title, a body and a URL. Whether this
 * person wanted this category of notification was decided on the server before
 * anything was sent, and the interesting data stays behind the app's own auth
 * rather than riding along in a push message.
 */
self.addEventListener('push', (event) => {
  let payload = {}
  try {
    payload = event.data ? event.data.json() : {}
  } catch {
    payload = { title: 'Meridian', body: event.data ? event.data.text() : '' }
  }

  const title = payload.title || 'Meridian'
  event.waitUntil(
    self.registration.showNotification(title, {
      body: payload.body || '',
      icon: '/icons/icon-192.png',
      badge: '/icons/icon-192.png',
      // Lets a later push about the same flight replace the earlier one rather
      // than stacking six notifications about one delay.
      tag: payload.tag || undefined,
      renotify: Boolean(payload.tag && payload.renotify),
      data: { url: payload.url || '/' },
      timestamp: Date.now(),
    }),
  )
})

self.addEventListener('notificationclick', (event) => {
  event.notification.close()
  const target = event.notification.data?.url || '/'

  event.waitUntil(
    (async () => {
      const all = await self.clients.matchAll({ type: 'window', includeUncontrolled: true })
      // Focus an open window rather than opening a second copy of the app.
      for (const client of all) {
        const url = new URL(client.url)
        if (url.origin === self.location.origin && 'focus' in client) {
          if ('navigate' in client && url.pathname !== target) await client.navigate(target)
          return client.focus()
        }
      }
      return self.clients.openWindow(target)
    })(),
  )
})

/**
 * The browser rotated the subscription out from under us.
 *
 * Nothing can be done from here without the app's credentials, so the old
 * endpoint is reported to a page next time one is open; `usePush` re-subscribes
 * on load anyway, which covers the common case.
 */
self.addEventListener('pushsubscriptionchange', (event) => {
  event.waitUntil(
    (async () => {
      const all = await self.clients.matchAll({ type: 'window', includeUncontrolled: true })
      for (const client of all) client.postMessage({ type: 'PUSH_SUBSCRIPTION_CHANGED' })
    })(),
  )
})
